#!/usr/bin/env node
// Enforces the repo's branch naming convention: <type>/<kebab-case-slug>,
// where <type> matches the Conventional Commits types allowed by
// commitlint.config.js. Mirrors PR title enforcement in
// .github/workflows/pr-title.yml so branch, commit, and PR naming agree.
import { execSync } from "node:child_process";

const TYPES = [
  "feat",
  "fix",
  "docs",
  "style",
  "refactor",
  "perf",
  "test",
  "build",
  "ci",
  "chore",
  "revert",
];

const EXEMPT = new Set(["main", "master", "develop"]);
// Branches auto-generated by tooling (e.g. Claude Code worktrees) aren't
// human-chosen task names, so they're exempt from the slug convention.
const EXEMPT_PREFIXES = ["worktree-"];

const PATTERN = new RegExp(`^(${TYPES.join("|")})/[a-z0-9]+(-[a-z0-9]+)*$`);

const branch = execSync("git rev-parse --abbrev-ref HEAD").toString().trim();

if (
  EXEMPT.has(branch) ||
  branch === "HEAD" ||
  EXEMPT_PREFIXES.some((prefix) => branch.startsWith(prefix))
) {
  process.exit(0);
}

if (!PATTERN.test(branch)) {
  console.error(`
✖ Branch name "${branch}" doesn't follow the repo convention.

  Expected: <type>/<kebab-case-slug>
  Types:    ${TYPES.join(", ")}
  Example:  feat/backend-feature-barrels

  Rename with: git branch -m <type>/<slug>
`);
  process.exit(1);
}
